(()=>{const definitions=window.BALLOON_ACHIEVEMENTS;let state;try{state=JSON.parse(localStorage.getItem('balloon-achievements'))}catch{}state=Object.assign({pops:0,modes:[],unlocked:[],activeSeconds:0,counts:{}},state||{});const save=()=>{try{localStorage.setItem('balloon-achievements',JSON.stringify(state))}catch{}};const sync=()=>window.balloonDesktop?.syncAchievements(state.unlocked).catch(()=>{});const value=d=>d.metric==='modes'?state.modes.length:d.metric==='pops'?state.pops:d.metric==='activeSeconds'?state.activeSeconds:d.metric.startsWith('visited:')?Number(state.modes.includes(d.metric.slice(8))):state.counts[d.metric]||0;function update(){let changed=false;for(const d of definitions)if(value(d)>=d.goal&&!state.unlocked.includes(d.id)){state.unlocked.push(d.id);changed=true}save();if(changed)sync()}const count=k=>state.counts[k]=(state.counts[k]||0)+1;let lastActivity=performance.now();window.balloonAchievements={pop(info={}){lastActivity=performance.now();state.pops++;if(info.mode)count('mode:'+info.mode);if(info.color)count('color:'+info.color);if(info.mode==='Shapes'&&info.value)count('shape:'+info.value);if(info.mode==='Normal'){if(info.idx===10)count('special:heart');else if(info.symbol)count('special:'+info.symbol)}update()},mode(m){lastActivity=performance.now();if(!state.modes.includes(m))state.modes.push(m);update()},round(m){count('round:'+m);update()}};let last=performance.now();setInterval(()=>{const now=performance.now(),delta=Math.min(2,(now-last)/1000);last=now;if(!document.hidden&&document.querySelector('#game').dataset.screen==='play'&&document.querySelector('#modal').hidden&&now-lastActivity<60000){state.activeSeconds+=delta;update()}},1000);addEventListener('pagehide',save);document.addEventListener('visibilitychange',save);window.balloonAchievements.show=()=>{window.balloonVoice?.stop();const modal=document.querySelector('#modal');modal.hidden=false;for(const s of ['#scene','#menu','nav'])document.querySelector(s).inert=true;let filter='all';const render=()=>{modal.innerHTML=`<div class="panel" role="dialog" aria-modal="true" aria-label="Achievements"><button class="close" aria-label="Close">×</button><h1>Achievements</h1><p>${state.unlocked.length} / ${definitions.length} discovered</p><div class="achievement-filters">${[['all','All'],['locked','To discover'],['unlocked','Discovered']].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div id="achievement-list">${definitions.filter(d=>filter==='all'||state.unlocked.includes(d.id)===(filter==='unlocked')).map(d=>{const unlocked=state.unlocked.includes(d.id),n=Math.min(value(d),d.goal);return `<div class="achievement"><img src="assets/achievements/${d.art}${unlocked?'':'-locked'}.png" alt="" width="64" height="64"><div><strong>${d.name}</strong><p>${d.description}</p><progress value="${n}" max="${d.goal}"></progress><small>${Math.floor(n)} / ${d.goal}${unlocked?' · Discovered':''}</small></div></div>`}).join('')}</div></div>`;modal.querySelector('.close').onclick=()=>{modal.hidden=true;for(const s of ['#scene','#menu','nav'])document.querySelector(s).inert=false};modal.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()})};render()};document.querySelector('#achievements').onclick=()=>{if(document.querySelector('#game').dataset.screen==='play')return;gate('achievements')};update();sync()})();
